add_action( 'woocommerce_single_product_summary', 'perfectpixel_show_total_sales', 11 );

function perfectpixel_show_total_sales() {
	global $product;
	if ( ! $product ) {
		return;
	}
	$sales = (int) $product->get_total_sales();
	if ( $sales >= max( 1, (int) '{{total_sales_min}}' ) ) {
		echo '<p class="perfectpixel-total-sales">' . esc_html( str_replace( '{count}', number_format_i18n( $sales ), '{{total_sales_text}}' ) ) . '</p>';
	}
}
